cProfile.replacementOfPublisherRun:
if role == "fleet":
        import cProfile
        profiler = cProfile.Profile()
        try:
            profiler.runcall(publisher.run)
        finally:
            profiler.dump_stats('/tmp/tmux-observer-capacity-fleet-3a.pstats')
    else:
        publisher.run()
    return 0

stageTimers.replacementOfPublisherRun:
if role == "fleet":
        measurements = []
        def wrap(target, name):
            original = getattr(target, name)
            def measured(*args, **kwargs):
                start = time.monotonic_ns()
                try:
                    return original(*args, **kwargs)
                finally:
                    elapsed = (time.monotonic_ns() - start) / 1000000
                    if elapsed >= 10 and len(measurements) < 5000:
                        measurements.append({"stage": name, "started": start / 1000000, "ms": elapsed, "readers": len(publisher.hub.peers) if publisher.hub else 0})
            setattr(target, name, measured)
        for name in ("connection_tick", "project_changed", "frame", "desktop_tick", "publish_tickets"):
            wrap(publisher, name)
        from tmux_observer._hub import SocketHub
        for name in ("broadcast", "poll", "frame", "process_requests"):
            wrap(SocketHub, name)
        try:
            publisher.run()
        finally:
            Path('/tmp/tmux-observer-capacity-fleet-3a-stages.json').write_text(json.dumps(measurements))
    else:
        publisher.run()
    return 0
